WITH enriched AS (SELECT id, full_name, email, manager_id, salary, hire_date, FIRST_VALUE(level) IGNORE NULLS OVER w_part AS first_known_level, DENSE_RANK() OVER w_ordered AS salary_dense_rank, SUM(salary) OVER w_part_2 AS cumulative_salary, SUM(salary) OVER (PARTITION BY manager_id ORDER BY hire_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary_2, ROUND(salary / SUM(salary) OVER (PARTITION BY level), 4) AS salary_share FROM employees WINDOW w_part AS (PARTITION BY level ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_ordered AS (ORDER BY salary DESC), w_part_2 AS (PARTITION BY job_title ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT DATE_TRUNC('MONTH', hire_date) AS activity_month, PERCENTILE_APPROX(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, COUNT(*) AS event_count FROM enriched GROUP BY DATE_TRUNC('MONTH', hire_date) ORDER BY event_count DESC NULLS FIRST;
